import torch
from clharness.train.hooks import BaseHook

class LowerBlockRollback(BaseHook):
    def on_run_start(self, ctx):
        self.reference = {}
        self.domains_finished = 0
        for name, parameter in ctx.model.named_parameters():
            parts = name.split('.')
            selected = False
            for index in range(len(parts) - 1):
                if parts[index] in ('layers', 'h', 'blocks'):
                    if parts[index + 1].isdigit():
                        if int(parts[index + 1]) < 13:
                            selected = True
            if selected:
                self.reference[name] = parameter.detach().clone()

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.domains_finished += 1
        if self.domains_finished == 2:
            for name, parameter in ctx.model.named_parameters():
                if name in self.reference:
                    parameter.lerp_(self.reference[name], 0.5)

import torch
from clharness.train.hooks import BaseHook

class EmbeddingEndpointRollback(BaseHook):
    def on_run_start(self, ctx):
        self.weight = ctx.model.get_input_embeddings().weight
        self.reference = self.weight.detach().clone()
        self.domains_finished = 0

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.domains_finished += 1
        if self.domains_finished == 2:
            self.weight.lerp_(self.reference, 0.5)

import torch
import math
from clharness.train.hooks import BaseHook

class CompensatedLowerRollback(BaseHook):
    def on_run_start(self, ctx):
        self.reference = {}
        self.lower = set()
        self.finished = 0
        for name, parameter in ctx.model.named_parameters():
            self.reference[name] = parameter.detach().clone()
            parts = name.split('.')
            for index in range(len(parts) - 1):
                if parts[index] in ('layers', 'h', 'blocks'):
                    if parts[index + 1].isdigit():
                        if int(parts[index + 1]) < 13:
                            self.lower.add(name)

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.finished += 1
        if self.finished != 2:
            return
        lower_energy = 0.0
        other_energy = 0.0
        for name, parameter in ctx.model.named_parameters():
            delta = parameter.float() - self.reference[name].float()
            energy = delta.square().sum().item()
            if name in self.lower:
                lower_energy += energy
            else:
                other_energy += energy
        if other_energy <= 1e-20:
            return
        scale = math.sqrt((other_energy + 0.75 * lower_energy) / other_energy)
        for name, parameter in ctx.model.named_parameters():
            reference = self.reference[name].float()
            factor = 0.5 if name in self.lower else scale
            delta = parameter.float() - reference
            parameter.copy_(reference + factor * delta)

