class MatchedLowerMlpAveraging(BaseHook):
    def on_run_start(self, ctx):
        self.reference = {}
        self.lower = set()
        self.selected = set()
        self.finished = 0
        for name, parameter in ctx.model.named_parameters():
            self.reference[name] = parameter.detach().clone()
            parts = name.split('.')
            for index in range(len(parts) - 1):
                if parts[index] in ('layers', 'h', 'blocks'):
                    if parts[index + 1].isdigit():
                        if int(parts[index + 1]) < 13:
                            self.lower.add(name)
                            if 'mlp' in parts:
                                self.selected.add(name)

    @torch.no_grad()
    def on_domain_end(self, ctx, domain):
        self.finished += 1
        if self.finished != 2:
            return
        total_energy = 0.0
        lower_energy = 0.0
        selected_energy = 0.0
        for name, parameter in ctx.model.named_parameters():
            delta = parameter.float() - self.reference[name].float()
            energy = delta.square().sum().item()
            total_energy += energy
            if name in self.lower:
                lower_energy += energy
            if name in self.selected:
                selected_energy += energy
        other_energy = total_energy - selected_energy
        if other_energy <= 1e-20 or selected_energy <= 1e-20:
            return
        target_energy = max(0.0, total_energy - 0.75 * lower_energy)
        other_scale = math.sqrt(max(0.0, target_energy - 0.25 * selected_energy) / other_energy)
        for name, parameter in ctx.model.named_parameters():
            reference = self.reference[name].float()
            delta = parameter.float() - reference
            factor = 0.5 if name in self.selected else other_scale
            parameter.copy_(reference + factor * delta)

